-- ============================================================
-- CAOS ASTRAL — Seed: cenas_grau (360 graus)
--
-- RECONSTRUÍDO em 01/08 pelo agente de front, depois da troca de
-- projeto Supabase (banco antigo deletado, projeto novo vazio).
--
-- FONTE: este conteúdo NÃO foi inventado nem reconstruído de memória —
-- veio direto de graus-caos-astral/graus-caos-astral-completo.json,
-- que já estava versionado neste mesmo repo (conteúdo autoral
-- 100% original do Micael, 360 entradas, validado 1:1 — 12 signos ×
-- 30 graus, todos os campos presentes, sem duplicata/falta). Esse JSON
-- é a fonte de verdade; este .sql é só a mesma informação em formato
-- de INSERT.
--
-- Rodar depois de 0001_schema.sql (precisa da tabela cenas_grau já
-- existir, com a coluna 'versao' — compute-natal-chart filtra
-- .eq("versao", "v1")).
-- ============================================================

on conflict (signo, grau, versao) do update set
  decanato = excluded.decanato,
  tempero = excluded.tempero,
  imagem = excluded.imagem,
  leitura = excluded.leitura;
