insert into public.cenas_grau (signo, grau, decanato, tempero, imagem, leitura, versao) values
  ('áries', 1, 1, 'marte', 'uma faísca salta de duas pedras batendo às cegas no escuro.', 'o impulso nasce antes de qualquer plano, não é erro, é o motor tentando ligar. serve pra começar, não pra sustentar sozinho.', 'v1'),
  ('áries', 2, 1, 'marte', 'um corredor dispara antes do tiro de largada soar.', 'a pressa aqui não é falta de disciplina, é o núcleo testando se a pista já existe.', 'v1'),
  ('áries', 3, 1, 'marte', 'uma porta é chutada aberta antes de alguém verificar o que tem do outro lado.', 'entrar sem checar é o risco e o combustível do mesmo gesto, o que tem do outro lado só se descobre depois.', 'v1'),
  ('áries', 4, 1, 'marte', 'um recém-nascido solta o primeiro grito antes de saber que existe um mundo fora.', 'presença antes de contexto. reivindicar espaço não precisa de permissão prévia.', 'v1'),
  ('áries', 5, 1, 'marte', 'uma lâmina recém-forjada, ainda quente, corta o primeiro objeto que encontra.', 'força recém-feita não escolhe alvo com cuidado ainda, ela só corta pra confirmar que corta.', 'v1'),
  ('áries', 6, 1, 'marte', 'um cachorro puxa a coleira na direção contrária de quem segura.', 'o impulso quer ir mais rápido que quem seria responsável por ele. a tensão é o dado, não o defeito.', 'v1'),
  ('áries', 7, 1, 'marte', 'um fósforo é riscado dentro de um cômodo cheio de gás.', 'ação sem inventário do risco. pode ser coragem ou descuido, a diferença só aparece depois do estalo.', 'v1'),
  ('áries', 8, 1, 'marte', 'uma criança derruba a torre de blocos só pra ver ela cair.', 'destruir também é forma de aprender a mecânica de alguma coisa. não é sabotagem, é curiosidade crua.', 'v1'),
  ('áries', 9, 1, 'marte', 'um motor é ligado antes do óleo terminar de circular.', 'pressa de funcionar antes de estar pronto, pode falhar, mas também é assim que motor aprende a rodar.', 'v1'),
  ('áries', 10, 1, 'marte', 'uma flecha já solta, ainda no ar, sem poder ser chamada de volta.', 'decisão que já não aceita revisão. depois desse grau, o que importa é mirar antes, não depois.', 'v1'),
  ('áries', 11, 2, 'sol', 'um ator pisa no palco antes de decorar a última fala.', 'performar antes de dominar. a plateia raramente nota o que falta, só quem está no palco sabe.', 'v1'),
  ('áries', 12, 2, 'sol', 'uma bandeira é fincada no topo antes de contar quantos já chegaram lá.', 'reivindicar o topo antes de confirmar a companhia. vitória e solidão chegam juntas nesse grau.', 'v1'),
  ('áries', 13, 2, 'sol', 'um leão marca território rugindo, sem checar se há outro leão por perto.', 'presença que ocupa espaço primeiro, negocia depois, ou nunca.', 'v1'),
  ('áries', 14, 2, 'sol', 'alguém assina o próprio nome em letra garrafal, embaixo de uma promessa que ainda não cumpriu.', 'o nome já ocupa o espaço que o resultado ainda vai ter que preencher.', 'v1'),
  ('áries', 15, 2, 'sol', 'uma vitrine é montada com o produto ainda incompleto.', 'mostrar antes de terminar. funciona se o resto for entregue rápido, se não, vira só fachada.', 'v1'),
  ('áries', 16, 2, 'sol', 'um general aponta a espada pro horizonte antes de contar os próprios soldados.', 'convicção que sai na frente do inventário. quem segue por trás precisa ser perguntado, não presumido.', 'v1'),
  ('áries', 17, 2, 'sol', 'um foguete de artifício sobe sozinho, barulhento, sem plateia nenhuma olhando.', 'brilhar não depende de quem está olhando, mas sem ninguém olhando, a energia também se perde rápido.', 'v1'),
  ('áries', 18, 2, 'sol', 'uma pessoa se declara campeã antes do juiz apitar o fim do jogo.', 'confiança que aposta no resultado antes de garanti-lo. pode ser profecia ou pode ser vexame, o jogo ainda não acabou.', 'v1'),
  ('áries', 19, 2, 'sol', 'uma fogueira é acesa alta demais pro tamanho da lenha que a sustenta.', 'entusiasmo maior que a estrutura disponível. bonito enquanto dura, exige mais lenha rápido.', 'v1'),
  ('áries', 20, 2, 'sol', 'um espelho é quebrado só pra ver os cacos multiplicando o próprio reflexo.', 'precisar de mais de uma imagem de si pra se sentir inteiro. cada caco ainda é você, só fragmentado.', 'v1'),
  ('áries', 21, 3, 'júpiter', 'um cavaleiro cruza a fronteira do mapa conhecido sem perguntar o que tem depois.', 'ir além do que já foi testado, sem esperar relatório de quem já foi lá.', 'v1'),
  ('áries', 22, 3, 'júpiter', 'uma seta é apontada pro horizonte mais distante que os olhos alcançam.', 'mirar mais longe do que os olhos alcançam. a pontaria aqui é fé funcional, não garantia.', 'v1'),
  ('áries', 23, 3, 'júpiter', 'alguém prega um sermão pra uma plateia que ainda não chegou.', 'convicção que fala antes de ter quem escute. ou é visão, ou é ensaio, só o tempo separa as duas.', 'v1'),
  ('áries', 24, 3, 'júpiter', 'um viajante joga fora o mapa e confia só na bússola.', 'trocar instrução externa por direção interna. funciona se a bússola for confiável, e só dá pra saber tentando.', 'v1'),
  ('áries', 25, 3, 'júpiter', 'um professor bate o livro na mesa no meio da própria explicação, exigindo mais.', 'convicção que empurra além do previsto, mesmo no meio do próprio raciocínio.', 'v1'),
  ('áries', 26, 3, 'júpiter', 'uma trombeta anuncia a guerra antes do exército terminar de se formar.', 'declarar antes de estar pronto, o anúncio vira pressão pra alcançar o que já foi prometido.', 'v1'),
  ('áries', 27, 3, 'júpiter', 'um profeta grita a verdade numa praça vazia.', 'convicção que não precisa de plateia pra ser real, mas sem eco, fica sem saber se acertou.', 'v1'),
  ('áries', 28, 3, 'júpiter', 'um explorador planta a bandeira num pico ainda coberto de neblina, sem ver o outro lado.', 'reivindicar a conquista antes de ver o que tem do outro lado. coragem e pressa dividem o mesmo gesto.', 'v1'),
  ('áries', 29, 3, 'júpiter', 'um atleta cruza a linha de chegada e já aponta pro próximo campeonato.', 'nunca descansar na conquista feita, o grau que já vive no próximo ciclo antes de fechar o atual.', 'v1'),
  ('áries', 30, 3, 'júpiter', 'um foguete deixa a atmosfera, motor rugindo, sem olhar pra trás pro chão que deixou.', 'ruptura total com o que ficou pra trás. fim de um ciclo que não pede licença pra outro começar. (grau anarético)', 'v1'),
  ('touro', 1, 1, 'vênus', 'Uma mão fecha em volta de uma fruta madura antes de perguntar se pode colher.', 'O corpo quer primeiro, pergunta depois. Desejo cru não pede licença, só reconhecimento.', 'v1'),
  ('touro', 2, 1, 'vênus', 'Um bebê agarra o dedo de quem o segura e não solta.', 'Segurar é o primeiro modo de confirmar que algo é seu.', 'v1'),
  ('touro', 3, 1, 'vênus', 'Uma raiz se enterra mais fundo antes de a árvore crescer um centímetro visível.', 'Construir base invisível antes de qualquer resultado que apareça por fora.', 'v1'),
  ('touro', 4, 1, 'vênus', 'Alguém prova o primeiro gole de um vinho e fecha os olhos.', 'Prazer que exige atenção total pra ser sentido de verdade, não só consumido.', 'v1'),
  ('touro', 5, 1, 'vênus', 'Um cofre é trancado antes mesmo de guardar o que ainda não chegou.', 'Proteger o que ainda vai vir. Prevenção que às vezes chega cedo demais.', 'v1'),
  ('touro', 6, 1, 'vênus', 'Uma vaca pasta devagar num campo enorme, sem pressa de terminar.', 'Ritmo que não se apressa por ninguém, o tempo dela é a única métrica que importa.', 'v1'),
  ('touro', 7, 1, 'vênus', 'Uma pedra preciosa é encontrada em bruto, ainda coberta de terra.', 'Valor real que ainda não foi lapidado nem reconhecido por ninguém além de quem achou.', 'v1'),
  ('touro', 8, 1, 'vênus', 'Duas mãos amassam barro até virar forma.', 'Paciência física que transforma matéria bruta em algo com propósito.', 'v1'),
  ('touro', 9, 1, 'vênus', 'Um cão enterra um osso num lugar que só ele lembra.', 'Guardar recursos com uma lógica que só faz sentido pra quem guardou.', 'v1'),
  ('touro', 10, 1, 'vênus', 'Uma âncora é lançada e prende no fundo do mar.', 'Parar de vez, fincar posição, fim do decanato: não se mover mais até que valha a pena.', 'v1'),
  ('touro', 11, 2, 'mercúrio', 'Um joalheiro examina uma pedra sob lupa antes de dar o preço.', 'Avaliar com precisão o que antes era só desejo cru. O valor exige exame, não só vontade.', 'v1'),
  ('touro', 12, 2, 'mercúrio', 'Uma balança comercial pesa grãos, um punhado de cada vez.', 'Medir com cuidado o que se troca, prazer sem cálculo vira prejuízo.', 'v1'),
  ('touro', 13, 2, 'mercúrio', 'Um agricultor testa a terra com os dedos antes de plantar.', 'Verificar a condição real antes de investir esforço. Sentir o material, não assumir.', 'v1'),
  ('touro', 14, 2, 'mercúrio', 'Uma receita antiga é seguida à risca, colher por colher.', 'Repetir o que já funcionou, sem improviso, segurança que vem da fórmula testada.', 'v1'),
  ('touro', 15, 2, 'mercúrio', 'Um contador soma moedas numa mesa de madeira gasta.', 'Cuidar do que já existe, centavo por centavo, antes de sonhar com mais.', 'v1'),
  ('touro', 16, 2, 'mercúrio', 'Um artesão lixa a mesma superfície pela décima vez, buscando o acabamento certo.', 'Repetição que refina, não que cansa. O resultado só aparece depois de insistir.', 'v1'),
  ('touro', 17, 2, 'mercúrio', 'Um fazendeiro conserta a cerca antes que o gado escape.', 'Manutenção que evita perda maior depois. Prevenção enfadonha, mas eficaz.', 'v1'),
  ('touro', 18, 2, 'mercúrio', 'Uma costureira mede o tecido duas vezes antes de cortar uma vez.', 'Cautela que evita desperdício. O cálculo aqui protege o material, não o ego.', 'v1'),
  ('touro', 19, 2, 'mercúrio', 'Um comerciante organiza sua mercadoria em fileiras exatas.', 'Ordem que facilita o próximo passo, o que está arrumado já está meio resolvido.', 'v1'),
  ('touro', 20, 2, 'mercúrio', 'Uma mesa farta é posta, prato por prato, antes dos convidados chegarem.', 'Preparar fartura com antecedência. O que sustenta os outros também exige planejamento.', 'v1'),
  ('touro', 21, 3, 'saturno', 'Uma muralha de pedra é erguida bloco por bloco, sem pressa de terminar.', 'Construção que aceita ser lenta, porque o que se ergue rápido também cai rápido.', 'v1'),
  ('touro', 22, 3, 'saturno', 'Um carvalho antigo não se move nem com vento forte.', 'Raiz funda que recusa ceder, força que não precisa provar nada, só permanece.', 'v1'),
  ('touro', 23, 3, 'saturno', 'Um cofre de banco é fechado com três chaves diferentes, cada uma com um guardião.', 'Proteção que distribui responsabilidade, o valor grande demais pra confiar numa mão só.', 'v1'),
  ('touro', 24, 3, 'saturno', 'Um fazendeiro guarda grãos suficientes pra sobreviver ao inverno mais longo.', 'Provisão pensada pro pior cenário, não só pro dia de hoje.', 'v1'),
  ('touro', 25, 3, 'saturno', 'Uma estátua de pedra resiste séculos ao tempo, sem trocar de expressão.', 'Permanência que não pede aprovação de ninguém, só dura.', 'v1'),
  ('touro', 26, 3, 'saturno', 'Um cofre-forte é escondido atrás de uma parede comum, sem nenhuma marca visível.', 'Guardar valor sem ostentar, proteção que aposta na discrição, não na exibição.', 'v1'),
  ('touro', 27, 3, 'saturno', 'Um velho agricultor ainda planta árvores que só darão fruto depois que ele morrer.', 'Investir em algo que não vai colher, construir legado maior que a própria vida.', 'v1'),
  ('touro', 28, 3, 'saturno', 'Uma montanha de sal se acumula lentamente numa salina, grão por grão.', 'Acúmulo que não tem pressa nenhuma, o resultado só aparece depois de muito tempo repetindo o mesmo gesto.', 'v1'),
  ('touro', 29, 3, 'saturno', 'Um testamento é lacrado e guardado num cofre até a hora certa de ser aberto.', 'O que foi decidido com cuidado espera o momento certo pra valer.', 'v1'),
  ('touro', 30, 3, 'saturno', 'Uma pedra fundamental é assentada, e sobre ela toda a construção seguinte vai se apoiar.', 'O que se decide agora sustenta tudo que vem depois, grau anarético que fecha o ciclo virando alicerce.', 'v1'),
  ('gemeos', 1, 1, 'mercúrio', 'Duas crianças trocam segredos sussurrando ao mesmo tempo, sem esperar a vez uma da outra.', 'Trocar informação rápido demais pra processar tudo, o impulso de falar chega antes do de ouvir.', 'v1'),
  ('gemeos', 2, 1, 'mercúrio', 'Um telefone toca em duas casas ao mesmo tempo.', 'Estar em dois lugares ao mesmo tempo, mesmo sem sair do lugar.', 'v1'),
  ('gemeos', 3, 1, 'mercúrio', 'Uma pomba-correio carrega duas mensagens contraditórias em asas diferentes.', 'Duas versões da mesma verdade, ambas parcialmente certas.', 'v1'),
  ('gemeos', 4, 1, 'mercúrio', 'Um papagaio repete uma frase que ouviu sem entender o que ela significa.', 'Repetir informação antes de digerir seu sentido, comunicação que ainda não virou compreensão.', 'v1'),
  ('gemeos', 5, 1, 'mercúrio', 'Duas crianças gêmeas terminam a frase uma da outra.', 'Pensamento que se completa em dupla, mais rápido do que sozinho.', 'v1'),
  ('gemeos', 6, 1, 'mercúrio', 'Uma carta é escrita e reescrita três vezes antes de ser enviada.', 'A mente girando em volta da própria formulação, tentando acertar o tom certo.', 'v1'),
  ('gemeos', 7, 1, 'mercúrio', 'Um vendedor ambulante grita o preço da mercadoria pra quem passa apressado.', 'Informação lançada rápido, sem garantia de que alguém pare pra ouvir.', 'v1'),
  ('gemeos', 8, 1, 'mercúrio', 'Uma criança aprende a mesma palavra em dois idiomas no mesmo dia.', 'A mente absorvendo mais de um sistema ao mesmo tempo, sem cansar.', 'v1'),
  ('gemeos', 9, 1, 'mercúrio', 'Um jornal impresso sai com a tinta ainda fresca, borrando ao toque.', 'Notícia tão nova que ainda nem terminou de se fixar.', 'v1'),
  ('gemeos', 10, 1, 'mercúrio', 'Um bilhete é passado de mão em mão numa sala de aula até chegar torto ao destino.', 'A mensagem muda de forma a cada mão que a repassa, fim do decanato: a informação já não é mais a original.', 'v1'),
  ('gemeos', 11, 2, 'vênus', 'Duas pessoas conversam à mesa de um café, cada uma esperando a vez certa de falar.', 'Diálogo que aprende timing, trocar já não é só falar rápido, é escutar também.', 'v1'),
  ('gemeos', 12, 2, 'vênus', 'Uma carta de amor é escrita com caligrafia cuidadosa, cada palavra pesada antes de ser escrita.', 'Comunicação que já cuida do efeito que vai causar no outro.', 'v1'),
  ('gemeos', 13, 2, 'vênus', 'Dois comerciantes fecham negócio com um aperto de mão, sem contrato assinado.', 'Confiar na palavra dada, troca que aposta na relação, não só no documento.', 'v1'),
  ('gemeos', 14, 2, 'vênus', 'Um casal de dançarinos espelha os passos um do outro sem combinar antes.', 'Sincronia que nasce de prestar atenção no outro, não de plano prévio.', 'v1'),
  ('gemeos', 15, 2, 'vênus', 'Uma sala de negociação tem duas cadeiras de frente uma pra outra, mesma altura.', 'Diálogo que só funciona quando nenhum dos dois lados fala de cima.', 'v1'),
  ('gemeos', 16, 2, 'vênus', 'Um mediador senta entre duas partes brigando, sem tomar lado nenhum.', 'Equilíbrio que exige não escolher, a solução vem do meio, não de um dos extremos.', 'v1'),
  ('gemeos', 17, 2, 'vênus', 'Duas cartas são trocadas ao mesmo tempo pelo correio, cruzando no caminho.', 'Duas pessoas dizendo a mesma coisa sem saber que a outra já tinha dito.', 'v1'),
  ('gemeos', 18, 2, 'vênus', 'Um casal decide, junto, o nome que vão dar ao filho.', 'Decisão que só existe porque duas vontades se encontraram no meio.', 'v1'),
  ('gemeos', 19, 2, 'vênus', 'Uma balança de comerciante equilibra perfeitamente dois pesos diferentes.', 'Equilíbrio real, não fingido, as duas partes pesam o que dizem pesar.', 'v1'),
  ('gemeos', 20, 2, 'vênus', 'Um par de luvas é costurado de forma idêntica, mão esquerda e direita.', 'Simetria que serve pros dois lados igualmente, fim do decanato: a troca virou parceria.', 'v1'),
  ('gemeos', 21, 3, 'saturno', 'Um telégrafo transmite código através de fios que cruzam um continente inteiro.', 'A mensagem virou sistema, não depende mais de quem fala, só do código combinado.', 'v1'),
  ('gemeos', 22, 3, 'saturno', 'Um arquivista organiza milhares de cartas por data, sem ler o conteúdo de nenhuma.', 'Informação tratada como estrutura, não como sentimento, frieza que serve pra não se perder no meio de tanto dado.', 'v1'),
  ('gemeos', 23, 3, 'saturno', 'Uma rede de sinais de fumaça conecta postos de vigia distantes um do outro.', 'Comunicação que já não depende de proximidade, só do sistema estar de pé.', 'v1'),
  ('gemeos', 24, 3, 'saturno', 'Um matemático prova um teorema usando só símbolos, sem nenhuma palavra.', 'Linguagem que abandona a ambiguidade da fala comum em troca de precisão total.', 'v1'),
  ('gemeos', 25, 3, 'saturno', 'Um grupo de estranhos se organiza em silêncio, cada um sabendo exatamente sua função.', 'Coordenação que dispensa conversa, o sistema já foi combinado antes, agora só se executa.', 'v1'),
  ('gemeos', 26, 3, 'saturno', 'Uma biblioteca cataloga livros num sistema numérico que qualquer bibliotecário do mundo entende.', 'Linguagem universal que troca calor humano por alcance máximo.', 'v1'),
  ('gemeos', 27, 3, 'saturno', 'Um relógio de estação sincroniza o horário de uma cidade inteira.', 'Um único sinal organizando o comportamento de milhares de pessoas ao mesmo tempo.', 'v1'),
  ('gemeos', 28, 3, 'saturno', 'Uma rede de estradas conecta cidades que nunca se falaram diretamente.', 'Conexão que existe mesmo sem contato direto, infraestrutura no lugar de intimidade.', 'v1'),
  ('gemeos', 29, 3, 'saturno', 'Um satélite retransmite um sinal pra milhões de aparelhos ao mesmo tempo.', 'Alcance imenso, contato zero. Informação que chega em todo lugar e não pertence a ninguém em particular.', 'v1'),
  ('gemeos', 30, 3, 'saturno', 'Um código é traduzido automaticamente pra cem idiomas diferentes ao mesmo tempo.', 'Comunicação que se multiplica até perder o rosto de quem falou primeiro, grau anarético: fim de um jeito de trocar, início de outro totalmente impessoal.', 'v1'),
  ('cancer', 1, 1, 'lua', 'Um recém-nascido procura o calor do peito da mãe antes de abrir os olhos.', 'Instinto que age antes da consciência, buscar proteção nem precisa ser aprendido.', 'v1'),
  ('cancer', 2, 1, 'lua', 'Um caranguejo recua pra dentro da própria concha ao menor sinal de perigo.', 'Proteção automática. Recuar aqui não é fraqueza, é reflexo de sobrevivência.', 'v1'),
  ('cancer', 3, 1, 'lua', 'Uma mãe pássaro cobre os filhotes com as asas durante a tempestade.', 'Abrigo que se oferece sem cálculo, só resposta direta ao perigo.', 'v1'),
  ('cancer', 4, 1, 'lua', 'Uma criança segura o cobertor da infância mesmo já crescida.', 'Memória do conforto antigo que ainda ancora, mesmo sem necessidade prática.', 'v1'),
  ('cancer', 5, 1, 'lua', 'Uma maré sobe e cobre a praia inteira antes de recuar de novo.', 'Ciclo emocional que vai e volta sozinho, sem pedir licença pro relógio.', 'v1'),
  ('cancer', 6, 1, 'lua', 'Um cão fareja o cheiro de casa a quilômetros de distância.', 'Reconhecer pertencimento pelo instinto, antes de qualquer explicação racional.', 'v1'),
  ('cancer', 7, 1, 'lua', 'Uma criança chora ao ver a mãe sair da sala, mesmo sabendo que ela volta.', 'Medo de abandono que existe mesmo quando a razão já sabe que está seguro.', 'v1'),
  ('cancer', 8, 1, 'lua', 'Um ninho é forrado de penas macias antes do primeiro ovo ser posto.', 'Preparar o abrigo antes mesmo de precisar dele, cuidado que antecipa a necessidade.', 'v1'),
  ('cancer', 9, 1, 'lua', 'Uma concha vazia é carregada pela maré até a areia, ainda com a forma de quem já morou nela.', 'O formato de um lar antigo que permanece mesmo depois que quem morava foi embora.', 'v1'),
  ('cancer', 10, 1, 'lua', 'Uma criança dorme enroscada, protegendo o peito com os braços cruzados.', 'Proteger o centro mole de si mesmo, mesmo dormindo, mesmo sem ameaça visível.', 'v1'),
  ('cancer', 11, 2, 'marte', 'Uma mãe ursa ataca sem hesitar qualquer coisa que se aproxime dos filhotes.', 'Proteção que vira força total quando o que se ama está ameaçado.', 'v1'),
  ('cancer', 12, 2, 'marte', 'Um portão de ferro é trancado com três fechaduras diferentes.', 'Defesa redundante, quando o medo é grande, uma trava só nunca parece suficiente.', 'v1'),
  ('cancer', 13, 2, 'marte', 'Um cão de guarda não dorme enquanto sente um estranho perto do quintal.', 'Vigilância que não descansa até a ameaça sumir de vez.', 'v1'),
  ('cancer', 14, 2, 'marte', 'Uma família esconde o que é mais precioso embaixo do próprio chão da casa.', 'Proteger o que importa escondendo, não expondo, segurança que aposta no segredo.', 'v1'),
  ('cancer', 15, 2, 'marte', 'Uma serpente protege seus ovos enrolando o corpo inteiro ao redor deles.', 'Proteção que ocupa todo o espaço disponível, sem deixar brecha nenhuma.', 'v1'),
  ('cancer', 16, 2, 'marte', 'Uma fortaleza é construída com um único portão estreito, fácil de defender.', 'Reduzir os pontos fracos ao mínimo possível, proteção que pensa como ataque.', 'v1'),
  ('cancer', 17, 2, 'marte', 'Uma mulher esconde uma faca sob o travesseiro antes de dormir sozinha.', 'Preparar defesa mesmo sem ameaça confirmada, instinto que não relaxa fácil.', 'v1'),
  ('cancer', 18, 2, 'marte', 'Um lobo marca o território com o próprio cheiro, avisando os outros à distância.', 'Proteção que age antes do conflito, avisando limite sem precisar brigar ainda.', 'v1'),
  ('cancer', 19, 2, 'marte', 'Uma criança bate em quem tentou machucar o irmão mais novo.', 'Agressão que nasce só quando é preciso proteger alguém mais vulnerável.', 'v1'),
  ('cancer', 20, 2, 'marte', 'Uma casa é cercada por um muro alto, com cacos de vidro no topo.', 'Defesa que vira também isolamento, proteger tanto que ninguém mais entra, nem quem devia.', 'v1'),
  ('cancer', 21, 3, 'júpiter', 'Uma casa abre as portas pra abrigar quem perdeu a própria durante a enchente.', 'O cuidado que cabia só na família se expande pra quem precisa, mesmo sendo estranho.', 'v1'),
